#include <iostream>
#include <string_view>
#include <vector>
#include <iomanip>

struct Note {
    std::string_view name;
    unsigned frequency; // Hz
    double duration_ms; // milliseconds
};

namespace Pitches {
    constexpr unsigned RE2  = 148;
    constexpr unsigned MI2  = 164;
    constexpr unsigned SOL2 = 196;
    constexpr unsigned LA2  = 230;
    constexpr unsigned SI2  = 247;
    constexpr unsigned DO3  = 264;
    constexpr unsigned RE3  = 297;
    constexpr unsigned MI3  = 330;
    constexpr unsigned FAD2 = 188;
}

int main() {
    constexpr double d = 300.0;        // Quarter note (đen)
    constexpr double tr = 2.0 * d;     // Half note (trắng)
    constexpr double tro = 4.0 * d;    // Whole note (tròn)

    // Motif from Tien Quan Ca opening as transcribed in textbook
    std::vector<Note> melody = {
        {"Re2",  Pitches::RE2,  d},
        {"Mi2",  Pitches::MI2,  d},
        {"Re2",  Pitches::RE2,  d},
        {"Sol2", Pitches::SOL2, tr},
        {"Sol2", Pitches::SOL2, tro},
        {"La2",  Pitches::LA2,  d},
        {"Sol2", Pitches::SOL2, d},
        {"Si2",  Pitches::SI2,  tr}
    };

    std::cout << std::left << std::setw(8) << "Note"
              << std::setw(12) << "Freq (Hz)"
              << std::setw(15) << "Duration (ms)"
              << "Total Elapsed (ms)\n";
    std::cout << std::string(45, '-') << "\n";

    double total_time = 0.0;
    for (const auto& n : melody) {
        total_time += n.duration_ms;
        std::cout << std::left << std::setw(8) << n.name
                  << std::setw(12) << n.frequency
                  << std::setw(15) << n.duration_ms
                  << total_time << "\n";
    }

    return 0;
}

#include <iostream>
#include <cmath>
#include <iomanip>

struct Point {
    double x, y;
};

struct Circle {
    Point center;
    double radius;
};

// Compute circumcircle for triangle ABC (Exercise 6)
Circle circumcircleTriangle(Point a, Point b, Point c) {
    double d = 2.0 * (a.x * (b.y - c.y) + b.x * (c.y - a.y) + c.x * (a.y - b.y));
    double a_sq = a.x * a.x + a.y * a.y;
    double b_sq = b.x * b.x + b.y * b.y;
    double c_sq = c.x * c.x + c.y * c.y;

    double ux = (a_sq * (b.y - c.y) + b_sq * (c.y - a.y) + c_sq * (a.y - b.y)) / d;
    double uy = (a_sq * (c.x - b.x) + b_sq * (a.x - c.x) + c_sq * (b.x - a.x)) / d;
    double r = std::hypot(a.x - ux, a.y - uy);
    return {{ux, uy}, r};
}

// Compute circumcircle for rectangle (Exercise 7)
Circle circumcircleRect(double left, double top, double w, double h) {
    double cx = left + w / 2.0;
    double cy = top + h / 2.0;
    double r = std::hypot(w, h) / 2.0;
    return {{cx, cy}, r};
}

int main() {
    std::cout << std::fixed << std::setprecision(2);

    // Exercise 6 Verification: A(300, 20), B(100, 220), C(500, 220)
    Circle c1 = circumcircleTriangle({300.0, 20.0}, {100.0, 220.0}, {500.0, 220.0});
    std::cout << "Ex6 Triangle Circumcircle: Center=(" << c1.center.x << ", " << c1.center.y 
              << "), Radius=" << c1.radius << "\n";

    // Exercise 7 Verification: Left=100, Top=150, Width=120, Height=90
    Circle c2 = circumcircleRect(100.0, 150.0, 120.0, 90.0);
    std::cout << "Ex7 Rectangle Circumcircle: Center=(" << c2.center.x << ", " << c2.center.y 
              << "), Radius=" << c2.radius << "\n";

    return 0;
}
